function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 3 || arr.length > 100000) return 'arr needs 3 to 100000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each value is an integer from 0 to 10^6.';
  let i = 0;
  while (i + 1 < arr.length && arr[i] < arr[i + 1]) i++;
  if (i === 0 || i === arr.length - 1) return 'arr must rise and then fall, with the peak not at either end.';
  while (i + 1 < arr.length && arr[i] > arr[i + 1]) i++;
  if (i !== arr.length - 1) return 'arr must strictly rise to one peak and then strictly fall.';
  return null;
}

