function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 3 + Math.floor(rand() * 8);
  const maxStep = size === 'large' ? 400 : 3;
  // The peak sits anywhere from index 1 to n - 2, with the ends favoured now and then.
  const r = rand();
  const peak = r < 0.15 ? 1 : r < 0.3 ? n - 2 : 1 + Math.floor(rand() * (n - 2));
  const step = () => 1 + Math.floor(rand() * maxStep);
  const leftSteps = Array.from({ length: peak }, step);
  const rightSteps = Array.from({ length: n - 1 - peak }, step);
  const sum = (list) => list.reduce((a, b) => a + b, 0);
  const top = Math.max(sum(leftSteps), sum(rightSteps)) + Math.floor(rand() * (size === 'large' ? 100000 : 4));
  const arr = new Array(n);
  arr[peak] = top;
  for (let i = peak - 1; i >= 0; i--) arr[i] = arr[i + 1] - leftSteps[i];
  for (let i = peak + 1; i < n; i++) arr[i] = arr[i - 1] - rightSteps[i - peak - 1];
  return [arr];
}
